const puppeteer = require('puppeteer');
const path = require('path');

async function renderPoster() {
  const browser = await puppeteer.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();

  // Set viewport to A1 at 100 DPI (~2339 x 3307)
  await page.setViewport({ width: 2339, height: 3307, deviceScaleFactor: 1 });

  const htmlPath = 'file://' + path.resolve(__dirname, 'poster.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle0' });

  // Wait a bit for fonts to load and rendering to stabilize
  await page.evaluate(() => document.fonts.ready);
  await new Promise(r => setTimeout(r, 2000));

  await page.screenshot({ 
    path: '/app/output/final_poster.png',
    fullPage: true 
  });

  await browser.close();
}

renderPoster().catch(console.error);

